 @Test void policyIdentityIsTenantTypeOverlayStableAndAvailableToEveryType()throws Exception{String s=read("shale-data/src/main/java/com/shale/data/dao/FieldConfirmationDao.java");assertAll(()->assertTrue(s.contains("CaseDateTypePolicyKey")),()->assertTrue(s.contains("SYSTEM:")),()->assertTrue(s.contains("TYPE:")),()->assertFalse(s.contains("CaseDateSemanticRoleResolver")),()->assertFalse(s.contains("FormConfiguredFields")),()->assertFalse(s.contains("CaseTeam")));}
