 @Test void migrationAddsTypeIdentityBeforeDynamicallyCompilingItsReferences()throws Exception{String m=read("docs/sql/2026-09-24_case_date_type_confirmation_policy_phase2d.sql");int add=m.indexOf("ADD CaseDateTypePolicyKey"),dynamic=m.indexOf("EXEC sys.sp_executesql",add);assertAll(()->assertTrue(add>=0,"Migration must add the Case Date Type policy identity."),()->assertTrue(dynamic>add,"Statements referencing the new column must compile dynamically after ADD COLUMN."),()->assertFalse(m.substring(0,dynamic).matches("(?s).*CaseDateTypePolicyKey\\s+IS\\s+(?:NOT\\s+)?NULL.*"),"No static query may reference the newly added column."));}
 @Test void migrationRemovesAlterBlockersAndRestoresIdentityContracts()throws Exception{String m=read("docs/sql/2026-09-24_case_date_type_confirmation_policy_phase2d.sql");int dropCurrent=m.indexOf("DROP INDEX UX_FieldConfirmationPolicies_Current"),dropRevision=m.indexOf("DROP INDEX UX_FieldConfirmationPolicies_Field_Revision"),alter=m.indexOf("ALTER COLUMN FormKey");assertAll(()->assertTrue(dropCurrent>=0&&dropCurrent<alter,"Current-policy index must be dropped before FormKey becomes nullable."),()->assertTrue(dropRevision>=0&&dropRevision<alter,"Revision index must be dropped before FormKey becomes nullable."),()->assertTrue(m.contains("DROP CONSTRAINT FK_FieldConfirmationPolicies_FieldKey"),"The composite field identity FK must be removed before alteration."),()->assertTrue(m.contains("WITH CHECK ADD CONSTRAINT FK_FieldConfirmationPolicies_FieldKey"),"The trusted field identity FK must be restored."),()->assertTrue(m.contains("unexpected index or key constraint")),()->assertTrue(m.contains("user-created statistic")),()->assertTrue(m.contains("schema-bound dependency")),()->assertTrue(m.contains("CK_FieldConfirmationPolicies_Identity")));}
 @Test void migrationFailsClosedOnEnabledLegacyPolicyAndVerificationIsReadOnly()throws Exception{String m=read("docs/sql/2026-09-24_case_date_type_confirmation_policy_phase2d.sql"),v=read("docs/sql/2026-09-24_case_date_type_confirmation_policy_phase2d_verify.sql");assertAll(()->assertTrue(m.contains("Enabled New Intake field confirmation policies exist")),()->assertTrue(m.contains("CaseDateTypePolicyKey")),()->assertTrue(m.contains("BEGIN TRANSACTION")),()->assertTrue(m.contains("XACT_STATE()<>0 ROLLBACK")),()->assertFalse(v.contains("REPLACE_WITH")),()->assertFalse(v.matches("(?is).*(INSERT|UPDATE|DELETE|MERGE|ALTER|CREATE|DROP)\\s+dbo\\..*")),()->assertTrue(v.contains("explicit rollout decision")));}
 private static int count(String s,String n){int c=0,p=0;while((p=s.indexOf(n,p))>=0){c++;p+=n.length();}return c;}
